import os as _os
_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# THE DEUTERONOMY WALK 7b — THE COMPILE OF CHAPTER 9 (2026-09-19; the docket its own run under THE TWO-RUN RULE, on the owner's "Go"): THE EXAM DOCKET
# for Deuteronomy 9:1-29, written from the scan's dump (scratchpad/ch9_docket_dump.txt: the LINK rows = every Babylonian Talmud / Mishnah / Tosefta
# segment on the local shelf citing a verse of the chapter — the export's chapter 9 the DB's twenty-nine verses, no division map; the TOPIC rows = the
# Mishnah rows, the folio ranges of the 7b box's item (j) and the two midrash rows it names, read WHOLE; the CREDITED marks = addresses already
# verdicted in an earlier ledger, given their quick look here). Every address in the dump gets ONE verdict (parts A..C on disk, each a SPEC over the
# dump's own addresses); the coverage is COMPUTED from the dump, never typed; the ranges' sizes are read from the scan's own print (ch9_scan.out).
# Append-only. Sitting 6b's form (write_ch8_docket.py): every row read WHOLE from the start.
import re, os, sys, importlib.util, subprocess
from collections import Counter
ROOT = _ROOT
SCR = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SCR)
OUT = f'{ROOT}/logic/oral_triage/deu_09_ekev_exam_2026-09-19.md'
assert not os.path.exists(OUT), OUT
dump = open(f'{SCR}/ch9_docket_dump.txt', encoding='utf-8').read()
rows = re.findall(r'^## \[(LINK|TOPIC)\] (.+?)  (.*)$', dump, re.M)
ADDR, CRED = [], {}
for k, a, rest in rows:
    m = re.search(r'\{CREDITED: (.*?)\}', rest)
    if m: CRED[a.strip()] = m.group(1)
    ADDR.append((k, a.strip(), re.sub(r'\s*\{CREDITED:.*?\}', '', rest).strip()))
NL = sum(1 for k, _, _ in ADDR if k == 'LINK'); NT = len(ADDR) - NL
hdr_line = dump.split('\n', 1)[0]
assert hdr_line == 'ROWS %d LINK %d TOPIC %d CREDITED %d' % (len(ADDR), NL, NT, len(CRED)), (hdr_line, len(ADDR), NL, NT, len(CRED))
V = {}; STATS = []
for p in 'ABC':
    part = f'ch9_docket_{p}'
    spec = importlib.util.spec_from_file_location(part, f'{SCR}/{part}.py'); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    STATS.append(m.WHOLE_STATS)
    for addr, verdict, note in m.ROWS:
        assert addr not in V, ('duplicate verdict', addr)
        assert verdict in ('LAW', 'DERIVATION', 'DISPUTE', 'CONTEXT', 'OUTSIDE'), (addr, verdict)
        V[addr] = (verdict, note)
missing = [a for _, a, _ in ADDR if a not in V]; extra = [a for a in V if a not in {x[1] for x in ADDR}]
if missing or extra:
    print('MISSING', len(missing), missing); print('EXTRA', len(extra), extra); sys.exit(1)
cnt = Counter(vd for vd, _ in V.values())
cnt_link = Counter(V[a][0] for k, a, _ in ADDR if k == 'LINK'); cnt_topic = Counter(V[a][0] for k, a, _ in ADDR if k == 'TOPIC')
works = Counter(a.rsplit(' ', 1)[0] for k, a, _ in ADDR if k == 'LINK')
scan = open(f'{SCR}/ch9_scan.out', encoding='utf-8').read()
scan_r = scan[scan.index('THE RANGES SIZED:'):]
LONG = [(f'{w.replace("_", " ")} {a}-{z}', int(s), int(l)) for w, a, z, s, l in re.findall(r'^  (\S+)\s+(\d+[ab])-(\d+[ab])\s+(\d+) rows,\s+(\d+) link rows', scan_r, re.M)]   # read from the scan's print
MISH = [a for k, a, _ in ADDR if k == 'TOPIC' and not re.search(r'\d+[ab]:\d+$', a)]   # the Mishnah and midrash rows among the topic rows
assert sum(s - l for _, s, l in LONG) + len(MISH) == NT, (sum(s - l for _, s, l in LONG), len(MISH), NT)   # every range read WHOLE
ncred_link = sum(1 for k, a, _ in ADDR if k == 'LINK' and a in CRED); ncred_topic = sum(1 for k, a, _ in ADDR if k == 'TOPIC' and a in CRED)
verses = Counter(h for k, _, vs in ADDR if k == 'LINK' for h in re.findall(r'Deut 9:\d+', vs)); assert verses, 'no verse hits parsed from the LINK headers'
UNCITED = [v for v in range(1, 30) if f'Deut 9:{v}' not in verses]   # computed, never typed
LAWCELLS = Counter(m.group(1) for vd, note in V.values() if vd == 'LAW' for m in [re.search(r'\b(F[1-6])\b', note)] if m)
TOT = {k: sum(s[k] for s in STATS) for k in STATS[0]}; assert TOT['rows'] == len(ADDR), TOT
NWHOLE = sum(1 for vd, note in V.values() if '[whole:' in note); assert NWHOLE == TOT['corrected'] == 0, (NWHOLE, TOT)
NOUT = Counter(a.rsplit(' ', 1)[0] for a, (vd, _) in V.items() if vd == 'OUTSIDE')
hdr = (f'# THE EXAM DOCKET — Deuteronomy 9:1-29 (not for your righteousness: the frame — the nations greater and mightier, the Anakim, the consuming fire, the three reasons, the stiff neck; the calf retold — the forty days, the tablets of the covenant written with the finger of God, God\'s word to go down, the offer of a nation, the breaking before your eyes, the second forty, Aaron\'s peril, the calf ground to dust into the brook; the four provocations — Taberah, Massah, Kibroth-hattaavah, Kadesh-barnea; the intercession\'s second telling — Your people and Your inheritance, the fathers remembered, the land\'s taunt, the great power and the outstretched arm) — THE DEUTERONOMY WALK sitting 7b, THE DOCKET\'S OWN RUN (2026-09-19; DEUTERONOMY_WALK.md "Sitting 7b — THE COMPILE OF CHAPTER 9 … THE DESIGN", THE ORDER)\n'
       f'# DECLARED: the exam docket is the UNION (the standing rule of 2026-09-05) of (1) THE LINK-DRIVEN ROWS — every segment of the local shelf\'s Babylonian Talmud, Mishnah and Tosefta exports whose English cites a verse of Deuteronomy 9 (the scan ch9_docket_scan.py: {NL} rows in {len(works)} works) — and (2) THE TOPIC ROWS BY ADDRESS, the 7b box\'s item (j) sized by the scan and read WHOLE: Mishnah Avodah Zarah 3:1-3:10, Mishnah Ta\'anit 4:6-4:7, Avot 5:4 and 5:6, Mishnah Megillah 4:10, Mishnah Yoma 8:8-8:9; the folio ranges {", ".join(n for n, _, _ in LONG)}; the two midrash rows Vayikra Rabbah 10:5 and Devarim Rabbah 2:1 (Seder Olam Rabbah 6 NOT in the export\'s reachable form — its chapter keyed by name returned nothing; the second ascent\'s date stays the calendar parameter\'s open row). {len(CRED)} addresses CREDITED (read at an earlier sitting — the erection\'s docket, the Exodus triage ledger, chapter 4\'s docket the largest) and given their quick look here.\n'
       f'# THE TALMUD ADDRESSING: the export\'s index 0 is folio 1a (a page = index // 2 + 1; measured 2026-09-09); the Mishnah by chapter:mishnah.\n'
       f'# READ WHOLE FROM THE START (THE WHOLE-ROW RULE, owner-ruled 2026-09-17 — "never ever cut corners with the Talmud"): every row was printed WHOLE (ch9_docket_rows.py, N huge; the prints ch9_rows_A-C.txt) and read entire before its verdict was typed — no cut, no overlay; the parts\' WHOLE dicts empty, apply_whole\'s counts computed: {TOT["corrected"]} of {TOT["rows"]} rows corrected ({TOT["verdicts_changed"]} verdicts, {TOT["notes_changed"]} notes).\n'
       f'# THE VERDICTS: LAW names the cell of cold_run_not_righteousness.py (F1 the_frame, F2 the_calf_retold, F3 the_forty_days, F4 aarons_peril, F5 the_four_provocations, F6 the_intercession) or the callee\'s cell by CALL; DERIVATION a hook from the verse to a rule; DISPUTE a parameter row with two arms; CONTEXT; OUTSIDE a declared range\'s matter on another subject. The link census: LAW {cnt_link.get("LAW", 0)} / DERIVATION {cnt_link.get("DERIVATION", 0)} / DISPUTE {cnt_link.get("DISPUTE", 0)} / CONTEXT {cnt_link.get("CONTEXT", 0)} / OUTSIDE {cnt_link.get("OUTSIDE", 0)}; the topic census: LAW {cnt_topic.get("LAW", 0)} / DERIVATION {cnt_topic.get("DERIVATION", 0)} / DISPUTE {cnt_topic.get("DISPUTE", 0)} / CONTEXT {cnt_topic.get("CONTEXT", 0)} / OUTSIDE {cnt_topic.get("OUTSIDE", 0)}; LAW by cell {dict(sorted(LAWCELLS.items()))}. The verses cited by the link rows: {", ".join(f"{v} ({n})" for v, n in sorted(verses.items(), key=lambda kv: int(kv[0].split(":")[1])))}; UNCITED by any row: {UNCITED}.\n')
body = ''
last = None
for k, a, vs in ADDR:
    work = a.rsplit(' ', 1)[0]
    if work != last:
        body += f'\n## {work}\n'; last = work
    vd, note = V[a]
    body += f'- {a} [{k}{(" — " + vs) if vs else ""}{(" — CREDITED: " + CRED[a]) if a in CRED else ""}] — {vd}. {note}\n'
crowns = '''
## The finds (this docket's crowns)
- THE CALF'S DESTRUCTION AND THE FOURTH VERB THE RETELLING DROPS (Mishnah Avodah Zarah 3:3; Avodah Zarah 43b:19-20, 44a:1-3; Tosefta Avodah Zarah 4:3; Avodah Zarah 52a:4): R. Yosei's proof that grinding and scattering suffices stands on 9:21's OWN verbs — "I crushed it, grinding it thoroughly until it was fine as dust; and I threw its dust into the brook" — and the Rabbis answer from THE FIRST TELLING's fourth verb, "and made the children of Israel drink" (Exodus 32:20): a TEST as the sotah's, not a nullification; the retelling has burning, crushing, grinding and the brook and NO DRINKING — the readback row 9:21 VARIANT's omission is the dispute's hinge (the tape's calf_destroyed purpose=to_test from 44a:2); the brook the Kidron's kin (Asa's at 44a:3, Josiah's at the reading); a Jew's idol forbidden FROM ITS MAKING — "the calf that you had MADE" (52a:4; the tape's calf_made worshipped=False now with its row).
- THE DATE OF THE BREAKING — THE ANSWER SHEET AND THE CLOCK AGREE (Mishnah Ta'anit 4:6; Ta'anit 26a:14, 28b:8-10; Shabbat 88a:3): five things on the seventeenth of Tammuz, the tablets broken first; R. Yosei's seventh of Sivan (the giving and the ascent one day — Exodus 24:16, 24:18) plus twenty-four days of Sivan and sixteen of Tammuz = forty; the tape's markers (1, 3, 7) → (1, 4, 17) reproduce the row's own arithmetic (894379 → 894419); the Rabbis' sixth of Sivan (Shabbat 88a:3) the parameter's other arm — the tape holds R. Yosei's, the design's F3 grades it MATCH; the Ninth of Av's decree dated by Ta'anit 29a:2-7 through the tape's own reading-placed markers at Taberah, Hazeroth and the spies' return — the four provocations' lines carry those days.
- THE FORTY DAYS AS THE MEASURE OF PRAYER (Berakhot 32b:8-9, 34a:11; Devarim Rabbah 2:1; Menachot 99b:6; Megillah 21a:17; Yoma 75b:11): one who prolongs his prayer is assured — from "the forty days and forty nights that I fell down … and the LORD heard me that time also" (9:25-26 with 10:10); no limit to a prayer's length (R. Eliezer's long-winded student); the guard — prolong without expecting (32b:9); "I threw myself down" (9:18) among the TEN NAMES OF PRAYER (nipul — the Sifrei 26:7's twin); Moses on high did not eat (9:9) — THE FASTING'S SEAT IS THIS CHAPTER'S OWN (R. Yishmael cites 9:9, not 34:28 — the readback row 9:9's "supplied from 34:28" corrected by the shelf); "I sat" (9:9) against "I stood" (10:10) — Rava's easy standing and difficult sitting; the Torah given in forty days as the soul is formed in forty.
- THE INTERCESSION'S RULES (Berakhot 32a:14-31; 7a:5, 7a:23-25, 7a:29; 7a:34-36; Shabbat 89a:5; Shabbat 55a:5): "leave Me be" (9:14) — the matter depends on Moses (the well-wisher's parable); MOSES SEIZED HIM like a man his fellow's garment (32a:16 — Onkelos's supplied "leave your prayer" at the reading); the THREE-LEGGED CHAIR — the fathers' merit against Moses' one leg (32a:17, an a fortiori; 9:27's "remember Your servants"); vayechal — the VOW ANNULLED by the vows' own law (32a:19, a verbal analogy with Numbers 30:3), gave his life (32a:20), the attribute of mercy (32a:21), a sacrilege (32a:22), the fever (32a:23); the oath BY YOUR NAME endures (32a:24); THE TAUNT'S GRAMMAR — "not the ABILITY [yekholet]" the feminine noun (32a:27-28; 9:28 keeps the noun); GOD CONCEDED — "I have forgiven according to your word" (32a:29 — the tape's pardoned_and_decreed); do not placate in anger — "My face will go" (7a:5 — the second forty's timing); Moses' three requests after the calf, granted (7a:23-25; R. Meir's two, 7a:29) — Exodus 33:12-23 has NO LINE on the tape; EVERY PROMISE OF GOOD FULFILLED — 9:14's "a nation mightier and more numerous" fulfilled in Rehaviah's sons, 600,000 by the verbal analogy "many/many" (7a:34-36) — and its ONE retraction (Ezekiel 9:4, Shabbat 55a:5).
- THE MERIT OF THE FATHERS — A PARAMETER WITH TWO ARMS AND FOUR DATES (Shabbat 55a:11, 55a:13-16; Berakhot 32a:17): Shmuel — the letter tav, tama: the merit of the Patriarchs has CEASED; R. Yochanan — tachon, He will have mercy by it; from when — Hosea's days (Rav), HAZAEL's (Shmuel: "His covenant with Abraham, Isaac and Jacob, and would not destroy them" — 2 Kings 13:23, THE LAST TIME, the kin of 9:26-27's "do not destroy … remember Your servants Abraham, Isaac and Jacob"), Elijah's (R. Yehoshua ben Levi), Hezekiah's (R. Yochanan): F6's row on 9:27 — the merit pleaded at the calf as the chair's three legs, and the shelf's dispute on whether it still stands.
- AARON'S PERIL — HALF THE EDICT (Vayikra Rabbah 10:5; Mishnah Megillah 4:10; Sanhedrin 102a:5): "to destroy him" (9:20) — DESTRUCTION IS THE ERADICATION OF CHILDREN (Amos 2:9); since Moses prayed, HALF THE EDICT WAS WITHHELD — TWO DIED AND TWO REMAINED — "take Aaron and his sons with him" (Leviticus 8:2); R. Yehoshua ben Levi: prayer accomplishes half (Aaron), repentance all: THE EFFECT'S NAME from the row — destruction_halved, a STATUS on aaron written by the retrograde line, its two halves on the tape already (Nadab and Abihu's fire, Leviticus 10; the garments transferred at Hor, Numbers 20); THE READING LAW'S ASYMMETRY — Exodus's second account (Aaron's report, 32:21-24) read and NOT translated, Deuteronomy's telling of Aaron's peril translated (Onkelos 9:20 read whole at sitting 7); "at that time" a time ordained for calamity (R. Yosei's seats — Exodus 32:34's day of visiting among them).
- THE BREAKING APPROVED — MOSES' OWN REASONING, THREE SEATS OF ONE RULE (Shabbat 87a:2-5; Menachot 99a:12-99b:1; Bava Batra 14b:4-7; Nedarim 38a:8; Pesachim 87b:22): three things on his own perception; the a fortiori from the Paschal lamb's "no alien shall eat" to the tablets and the apostates; "the first tablets WHICH you broke" — may your strength be true (87a:5, 99b:1, 14b:7); THE FRAGMENTS IN THE ARK with the second tablets (10:1-2 forward; "the Name, the Name" 2 Samuel 6:2; 1 Kings 8:9) — the entry OWED to chapter 10's compile; the tablets six by six by three handbreadths — Moses' MIGHT read from 9:17's own verbs, not Exodus's; the letters flew back to their origin.
- THE TEN TRIALS — AND TABERAH NOT AMONG THEM (Avot 5:4; Arakhin 15a:6, 15a:9-20; Berakhot 32a:5): R. Yehuda's list — two at the sea, two with water (Marah; Rephidim = MASSAH, "why do you test the LORD"), two with the manna, two with the quail (KIBROTH the second), the calf (HOREB — 9:8), Paran (KADESH — 9:23, the tenth that SEALED the sentence: "now [zeh] ten times"); 9:22's TABERAH is NOT counted among the ten — the retelling names a provocation the answer sheet's list does not (a DATA row the design did not predict); Taberah's prayer read as impertinence (32a:5, Numbers 11:2 el/al); the spies' sin the evil report, not the blasphemy (15a:12-13).
- THE CALF'S DAY, CAUSE AND DEBT (Shabbat 89a:6; Berakhot 32a:8, 32a:13; Sanhedrin 102a:14-16; Berakhot 32b:15-19; Shabbat 88a:7, 88b:2, 88b:4): boshesh read BA'U SHESH — the fortieth day's sixth hour, Satan's storm and the bier in the cloud (the calf's own day and hour, the design's OPEN row — this row its shelf source if the owner rules a marker); DI ZAHAV — the wealth caused it, and God CONCEDED it (Hosea 2:10); THE SURCHARGE — one twenty-fourth of the first calf in every punishment (Exodus 32:34), collected twenty-four generations later (Ezekiel 9:1) — the calf's debt OPEN on the shelf against "these shall be forgotten" (Isaiah 49:15 = the calf; "I will not forget" = Sinai) — two registers, neither on the tape; the crowns removed at Horeb (Exodus 33:6 — NO LINE on the tape, a DATA row); the bride under her canopy, the kid forgiven in the Song's word.
- THE STIFF NECK AS THE REASON FOR THE TORAH (Beitzah 25b:7-8, 25b:5-6; Chullin 90b:12; Tamid 29a:8): R. Meir — the Torah was given to Israel BECAUSE THEY ARE IMPUDENT, to humble them; a FIERY LAW (33:2) for a people like fire; the three impudent ones — Israel among the nations, the dog, the rooster: 9:6's "stiff-necked people" the shelf's converse of "not for your righteousness" — the land not for merit, the Torah for impudence (F1's exam row); the lupine cooked seven times (Judges 10:6's seven idolatries — "rebellious from the day I knew you", 9:24); the hyperbole rule on 9:1 at two more seats (the Sifrei 25:4's twin).
- THE CONFESSION SPECIFIED (Yoma 86b:14; Mishnah Yoma 8:8-9): R. Yehuda ben Bava — the sin detailed, from "this people have sinned a great sin and made themselves a god of gold" (Exodus 32:31); R. Akiva — need not; R. Yannai — the gold an explanation: 9:18's "all your sin which you sinned" and 9:21's "your sin, the calf which you made" — the retelling specifies; the last tablets on the day of pardon (Mishnah Yoma 8:9's Yom Kippur; Ta'anit 30b the parameter's teacher).
- WHAT THE DESIGN DID NOT PREDICT (carried to RUN B as DATA rows or notes): TABERAH OUTSIDE THE TEN TRIALS (Arakhin 15a:14); THE EFFECT'S NAME — destruction_halved, from "half the edict was withheld" (Vayikra Rabbah 10:5), with its two halves already on the tape; the fasting's seat is 9:9's own (Yoma 75b:11 — the readback row 9:9's grade note corrected); the calf forbidden from its making (52a:4) — the tape's field with its row; the merit of the fathers a PARAMETER (Shabbat 55a:11) with 2 Kings 13:23 the run's last seat; the crowns of Horeb stripped with no line (Shabbat 88a:7 — Exodus 33:6); Mishnah Megillah 4:10's asymmetry (Aaron's report untranslated, the retelling translated); the letters flying back (Pesachim 87b:22); Moses' might from 9:17 (Nedarim 38a:8); the three requests of Exodus 33 with no line (Berakhot 7a:23-25); Seder Olam Rabbah 6 unreachable in the export — the second ascent's date stays OPEN.
'''
cite = '\n## CITE INDEX — every segment opened, each fully named\n(coverage COMPUTED by write_ch9_docket.py against the scan\'s dump: %d addresses, every one verdicted — missing 0, extra 0)\n' % len(ADDR)
cite += '\n'.join(a for _, a, _ in ADDR) + '\n'
tail = (f'\n**read: {len(ADDR)} of {len(ADDR)} — COMPLETE** (the link-driven rows {NL}: {", ".join(f"{k} {n}" for k, n in sorted(cnt_link.items()))}; '
        f'the topic windows {NT}: {", ".join(f"{k} {n}" for k, n in sorted(cnt_topic.items()))}; all rows: {", ".join(f"{k} {n}" for k, n in sorted(cnt.items()))}; credited {len(CRED)} — the counts this script computed from the dump and the verdict lists, never typed; every row read WHOLE from the start, corrections {TOT["corrected"]}; the ranges: {"; ".join(f"{n} {s} rows ({l} link)" for n, s, l in LONG)}; the Mishnah and midrash rows {len(MISH)}; OUTSIDE by work: {dict(NOUT)}.)\n')
open(OUT, 'w', encoding='utf-8').write(hdr + body + crowns + cite + tail)
print('WROTE', OUT, os.path.getsize(OUT), 'bytes')
print('rows', len(ADDR), 'link', NL, 'topic', NT, 'credited', len(CRED), '(link', ncred_link, 'topic', ncred_topic, ')')
print('verdicts', dict(sorted(cnt.items())), 'link', dict(sorted(cnt_link.items())), 'topic', dict(sorted(cnt_topic.items())))
print('LAW by cell', dict(sorted(LAWCELLS.items())))
print('OUTSIDE by work', dict(NOUT))
print('verses cited', sorted(verses.items(), key=lambda kv: int(kv[0].split(':')[1])), 'UNCITED', UNCITED)
